create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null check(length(display_name) between 2 and 80), bio text not null default '' check(length(bio)<=500), country text not null default '', language text not null default 'pt', avatar_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references profiles on delete cascade, ai_consent boolean not null default false, discoverable boolean not null default true, adult_confirmed_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.user_blocks (user_id uuid references profiles on delete cascade, blocked_id uuid references profiles on delete cascade, created_at timestamptz not null default now(), primary key(user_id,blocked_id),check(user_id<>blocked_id));
create table public.subscription_plans (id text primary key check(id in ('free','global','pro','business')), name text not null, monthly_cents integer not null check(monthly_cents>=0), translation_limit integer not null, rank integer not null unique);
insert into subscription_plans values ('free','Free',0,0,0),('global','Global',299,100,1),('pro','Pro',599,500,2),('business','Business',1990,1000,3);
create table public.subscriptions (user_id uuid primary key references profiles on delete cascade,plan_id text not null references subscription_plans default 'free',status text not null default 'inactive' check(status in ('active','inactive','past_due','canceled')),current_period_end timestamptz, stripe_customer_id text unique, stripe_subscription_id text unique, updated_at timestamptz not null default now());
create table public.payment_webhook_events (id text primary key,created_at timestamptz not null default now());
create table public.admin_roles (user_id uuid primary key references profiles on delete cascade,role text not null check(role in ('admin','moderator')));
create table public.admin_audit_logs (id uuid primary key default gen_random_uuid(),actor_id uuid references profiles on delete set null,action text not null,created_at timestamptz not null default now());
create function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.admin_roles where user_id=auth.uid()); $$;
create function private.plan_rank() returns integer language sql stable security definer set search_path='' as $$ select case when auth.uid() is null then 0 else coalesce((select p.rank from public.subscriptions s join public.subscription_plans p on p.id=s.plan_id where s.user_id=auth.uid() and s.status='active' and s.current_period_end>now()),0) end; $$;
create function private.blocked(other uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is null or exists(select 1 from public.user_blocks where (user_id=auth.uid() and blocked_id=other) or (blocked_id=auth.uid() and user_id=other)); $$;
create table public.posts (id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create index posts_created on posts(created_at desc);
create index posts_user on posts(user_id);
create table public.post_comments (id uuid primary key default gen_random_uuid(),post_id uuid not null references posts on delete cascade,user_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 1500),created_at timestamptz not null default now());
create index comments_post on post_comments(post_id);
create table public.post_reactions (post_id uuid references posts on delete cascade,user_id uuid references profiles on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.friend_requests (id uuid primary key default gen_random_uuid(),sender_id uuid not null references profiles on delete cascade,recipient_id uuid not null references profiles on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','declined')),created_at timestamptz not null default now(),unique(sender_id,recipient_id),check(sender_id<>recipient_id));
create table public.community_groups (id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text not null,required_rank integer not null default 0 check(required_rank between 0 and 3),created_at timestamptz not null default now());
insert into community_groups(slug,name,description,required_rank) values ('conexoes-globais','Conexões globais','Conheça mulheres, culturas e novas perspectivas.',0),('mulheres-da-ia','Mulheres da IA','Aprenda a usar inteligência artificial no seu dia a dia.',2),('canva-e-design','Canva e Design','Ideias visuais, portfólios e criatividade compartilhada.',2),('empreendedoras','Empreendedoras sem fronteiras','Troque experiências sobre negócios e marketing.',1);
create table public.group_members (group_id uuid references community_groups on delete cascade,user_id uuid references profiles on delete cascade,created_at timestamptz not null default now(),primary key(group_id,user_id));
create table public.group_posts (id uuid primary key default gen_random_uuid(),group_id uuid not null references community_groups on delete cascade,user_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create table public.conversations (id uuid primary key default gen_random_uuid(),member_a uuid not null references profiles on delete cascade,member_b uuid not null references profiles on delete cascade,created_at timestamptz not null default now(),check(member_a<member_b),unique(member_a,member_b));
create table public.messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations on delete cascade,sender_id uuid not null references profiles on delete cascade,body text not null check(length(body) between 1 and 5000),language text not null default 'pt',created_at timestamptz not null default now());
create index messages_conversation on messages(conversation_id,created_at);
create table public.user_reports (id uuid primary key default gen_random_uuid(),reporter_id uuid not null references profiles on delete cascade,reported_id uuid references profiles on delete set null,reason text not null check(length(reason) between 5 and 2000),status text not null default 'open' check(status in ('open','reviewed','closed')),created_at timestamptz not null default now());
create table public.membership_badges (id text primary key,label text not null,description text not null);
insert into membership_badges values ('rosa','Moeda Rosa','Símbolo de participação, sem valor monetário.');
create table public.badge_assignments (user_id uuid references profiles on delete cascade,badge_id text references membership_badges,created_at timestamptz not null default now(),primary key(user_id,badge_id));
create table public.business_profiles (id uuid primary key references profiles on delete cascade,name text not null check(length(name) between 2 and 100),description text not null check(length(description)<=2000),category text not null,contact_url text not null check(contact_url ~ '^https://'),created_at timestamptz not null default now());
create table public.business_listings (id uuid primary key default gen_random_uuid(),user_id uuid not null references business_profiles on delete cascade,title text not null check(length(title) between 2 and 120),description text not null check(length(description)<=2000),created_at timestamptz not null default now());
create table public.learning_resources (id uuid primary key default gen_random_uuid(),title text not null,description text not null,category text not null,url text check(url ~ '^https://'),required_rank integer not null default 2,created_at timestamptz not null default now());
create table public.support_resources (id uuid primary key default gen_random_uuid(),country text not null,name text not null,description text not null,url text not null check(url ~ '^https://'),verified_at timestamptz);
create table public.ai_usage (id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,kind text not null,created_at timestamptz not null default now());
create table public.data_requests (id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,kind text not null check(kind in ('export','delete')),status text not null default 'pending',created_at timestamptz not null default now());
create function private.owner_business_active(owner_id uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.subscriptions where user_id=owner_id and plan_id='business' and status='active' and current_period_end>now());$$;
create function private.message_allowed(cid uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.conversations c where c.id=cid and auth.uid() in (c.member_a,c.member_b) and not private.blocked(case when c.member_a=auth.uid() then c.member_b else c.member_a end));$$;
create function private.member_allowed(gid uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.group_members m join public.community_groups g on g.id=m.group_id where m.group_id=gid and m.user_id=auth.uid() and g.required_rank<=private.plan_rank());$$;
create function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin
 if coalesce(new.raw_user_meta_data->>'adult_confirmed','false')<>'true' then raise exception 'Adult confirmation required'; end if;
 insert into public.profiles(id,display_name) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'display_name',''),'Nova integrante'),80));
 insert into public.user_settings(user_id) values(new.id);
 insert into public.subscriptions(user_id) values(new.id);
 insert into public.badge_assignments values(new.id,'rosa',now());
 return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
create function private.rate_limit() returns trigger language plpgsql security definer set search_path='' as $$declare n integer;begin
 if auth.uid() is null then return new; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||tg_table_name,0));
 if tg_table_name='messages' then select count(*) into n from public.messages where sender_id=auth.uid() and created_at>now()-interval '1 minute';
 elsif tg_table_name='posts' then select count(*) into n from public.posts where user_id=auth.uid() and created_at>now()-interval '1 minute'; end if;
 if n>=10 then raise exception 'Aguarde um minuto antes de enviar novamente.';end if;
 new.created_at=now();return new;end;$$;
create trigger post_rate_limit before insert on posts for each row execute function private.rate_limit();
create trigger message_rate_limit before insert on messages for each row execute function private.rate_limit();
revoke all on all functions in schema private from public;
grant execute on function private.is_admin(),private.plan_rank(),private.blocked(uuid),private.owner_business_active(uuid),private.message_allowed(uuid),private.member_allowed(uuid) to authenticated;
DO $$declare t text;begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);end loop;end$$;
grant select on subscription_plans to anon,authenticated;
create policy plan_read on subscription_plans for select using(true);
grant select,insert,update on profiles to authenticated;
create policy profile_read on profiles for select to authenticated using(id=auth.uid() or (not private.blocked(id)));
create policy profile_update on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
grant select,update on user_settings to authenticated;
create policy settings_read on user_settings for select to authenticated using(user_id=auth.uid());
create policy settings_update on user_settings for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
grant select,insert,delete on user_blocks to authenticated;
create policy block_owner on user_blocks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
grant select on subscriptions,admin_roles,admin_audit_logs,ai_usage,badge_assignments,membership_badges to authenticated;
create policy sub_read on subscriptions for select to authenticated using(user_id=auth.uid() or private.is_admin());
create policy admin_read on admin_roles for select to authenticated using(user_id=auth.uid());
create policy audit_read on admin_audit_logs for select to authenticated using(private.is_admin());
create policy usage_read on ai_usage for select to authenticated using(user_id=auth.uid());
create policy badge_read on membership_badges for select to authenticated using(true);
create policy assigned_read on badge_assignments for select to authenticated using(user_id=auth.uid());
grant select,insert,delete on posts,post_comments,post_reactions to authenticated;
create policy post_read on posts for select to authenticated using(not private.blocked(user_id));
create policy post_insert on posts for insert to authenticated with check(user_id=auth.uid());
create policy post_delete on posts for delete to authenticated using(user_id=auth.uid() or private.is_admin());
create policy comment_read on post_comments for select to authenticated using(not private.blocked(user_id) and exists(select 1 from posts where id=post_id));
create policy comment_insert on post_comments for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from posts where id=post_id));
create policy comment_delete on post_comments for delete to authenticated using(user_id=auth.uid() or private.is_admin());
create policy reaction_read on post_reactions for select to authenticated using(exists(select 1 from posts where id=post_id));
create policy reaction_insert on post_reactions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from posts where id=post_id));
create policy reaction_delete on post_reactions for delete to authenticated using(user_id=auth.uid());
grant select,insert,update,delete on friend_requests to authenticated;
create policy friend_read on friend_requests for select to authenticated using(auth.uid() in (sender_id,recipient_id) and not private.blocked(case when sender_id=auth.uid() then recipient_id else sender_id end));
create policy friend_insert on friend_requests for insert to authenticated with check(sender_id=auth.uid() and status='pending' and not private.blocked(recipient_id));
create policy friend_update on friend_requests for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid() and not private.blocked(sender_id));
revoke update on friend_requests from authenticated;grant update(status) on friend_requests to authenticated;
create policy friend_delete on friend_requests for delete to authenticated using(auth.uid() in (sender_id,recipient_id));
grant select on community_groups to authenticated;
create policy groups_read on community_groups for select to authenticated using(true);
grant select,insert,delete on group_members,group_posts to authenticated;
create policy member_read on group_members for select to authenticated using(user_id=auth.uid());
create policy member_insert on group_members for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from community_groups where id=group_id and required_rank<=private.plan_rank()));
create policy member_delete on group_members for delete to authenticated using(user_id=auth.uid());
create policy gp_read on group_posts for select to authenticated using(private.member_allowed(group_id) and not private.blocked(user_id));
create policy gp_insert on group_posts for insert to authenticated with check(user_id=auth.uid() and private.member_allowed(group_id));
create policy gp_delete on group_posts for delete to authenticated using(user_id=auth.uid() or private.is_admin());
grant select,insert on conversations,messages to authenticated;
create policy convo_read on conversations for select to authenticated using(private.message_allowed(id));
create policy convo_insert on conversations for insert to authenticated with check(auth.uid() in (member_a,member_b) and not private.blocked(case when member_a=auth.uid() then member_b else member_a end) and exists(select 1 from friend_requests where status='accepted' and ((sender_id=member_a and recipient_id=member_b) or (sender_id=member_b and recipient_id=member_a))));
create policy message_read on messages for select to authenticated using(private.message_allowed(conversation_id));
create policy message_insert on messages for insert to authenticated with check(sender_id=auth.uid() and private.message_allowed(conversation_id));
grant select,insert on user_reports,data_requests to authenticated;
create policy report_read on user_reports for select to authenticated using(reporter_id=auth.uid() or private.is_admin());
create policy report_insert on user_reports for insert to authenticated with check(reporter_id=auth.uid() and status='open');
create policy request_read on data_requests for select to authenticated using(user_id=auth.uid() or private.is_admin());
create policy request_insert on data_requests for insert to authenticated with check(user_id=auth.uid() and status='pending');
grant select,insert,update,delete on business_profiles,business_listings to authenticated;
create policy business_read on business_profiles for select to authenticated using((id=auth.uid() or private.owner_business_active(id)) and not private.blocked(id));
create policy business_insert on business_profiles for insert to authenticated with check(id=auth.uid() and private.plan_rank()=3);
create policy business_update on business_profiles for update to authenticated using(id=auth.uid() and private.plan_rank()=3) with check(id=auth.uid() and private.plan_rank()=3);
create policy business_delete on business_profiles for delete to authenticated using(id=auth.uid());
create policy listing_read on business_listings for select to authenticated using((user_id=auth.uid() or private.owner_business_active(user_id)) and not private.blocked(user_id));
create policy listing_insert on business_listings for insert to authenticated with check(user_id=auth.uid() and private.plan_rank()=3);
create policy listing_update on business_listings for update to authenticated using(user_id=auth.uid() and private.plan_rank()=3) with check(user_id=auth.uid() and private.plan_rank()=3);
create policy listing_delete on business_listings for delete to authenticated using(user_id=auth.uid());
grant select on learning_resources to authenticated;
create policy learning_read on learning_resources for select to authenticated using(required_rank<=private.plan_rank());
grant select on support_resources to anon,authenticated;
create policy support_read on support_resources for select using(verified_at is not null);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',false,5242880,array['image/jpeg','image/png','image/webp']);
create policy avatar_read on storage.objects for select to authenticated using(bucket_id='avatars' and not private.blocked(((storage.foldername(name))[1])::uuid));
create policy avatar_insert on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_update on storage.objects for update to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_delete on storage.objects for delete to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
alter publication supabase_realtime add table public.messages;
